/// The sum `Session`.
public indirect enum Session: Equatable {
    case active(active: Active)
    case idle

    public init(json j: Any?) {
        let (t, o) = J.sum(j)
        switch t {
        case "Active": self = .active(active: Active(json: o!["active"]))
        case "Idle": self = .idle
        default: fatalError("Session: no variant \(t)")
        }
    }

    public var json: String {
        switch self {
        case let .active(active): return "{\"Active\":" + J.obj(["\"active\":" + active.json]) + "}"
        case .idle: return "\"Idle\""
        }
    }
}

